#!/usr/bin/env bash
set -euo pipefail

APP_ID=$(node -e "console.log(require('./capacitor.config.json').appId)")
MAIN=android/app/src/main
PKG_DIR="$MAIN/java/$(echo "$APP_ID" | tr . /)"

mkdir -p "$PKG_DIR" "$MAIN/res/layout" "$MAIN/res/xml" "$MAIN/res/drawable" "$MAIN/res/values"

# Files from the single-widget version. android/ is regenerated by CI so this is
# mostly a safety net for local runs.
rm -f "$PKG_DIR/QuitWidgetProvider.java" \
      "$MAIN/res/layout/widget_quit.xml" \
      "$MAIN/res/xml/quit_widget_info.xml" \
      "$MAIN/res/drawable/widget_bg.xml" \
      "$MAIN/res/values/widget_strings.xml" 2>/dev/null || true

# ---------------------------------------------------------------------------
# Shared widget logic: reads the values the web layer writes through
# @capacitor/preferences (SharedPreferences file "CapacitorStorage", raw keys),
# picks a layout from the current cell size, and paints it for the system's
# light or dark theme.
# ---------------------------------------------------------------------------
cat > "$PKG_DIR/UnlitWidgetBase.java" <<'EOF'
package __APP_ID__;

import android.app.PendingIntent;
import android.appwidget.AppWidgetManager;
import android.appwidget.AppWidgetProvider;
import android.content.ComponentName;
import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.content.res.Configuration;
import android.os.Bundle;
import android.util.TypedValue;
import android.view.View;
import android.widget.RemoteViews;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;
import org.json.JSONArray;
import org.json.JSONObject;

/**
 * Shared home-screen widget behaviour.
 *
 * Two widgets use this: `Unlit — days` (hero is the day count, tapping the
 * number opens the quick log dialog) and `Unlit — time` (hero is the elapsed
 * time, from minutes up to days). Both adapt their layout to the space the user
 * gives them: 2x2 shows only the hero, 2x4 stacks the details, 4x2 puts the
 * numbers beside the hero, 4x4 is the full card. Colours follow the system's
 * light/dark setting, so the same widget is black on white or white on black.
 */
public abstract class UnlitWidgetBase extends AppWidgetProvider {
    public static final String ACTION_REFRESH = "com.unlit.app.REFRESH_WIDGET";

    static final String PREFS = "CapacitorStorage";
    static final String KEY_PENDING = "unlit_pending_logs";

    static final int MODE_DAYS = 0;
    static final int MODE_CLOCK = 1;

    static final int SIZE_SMALL = 0;
    static final int SIZE_TALL = 1;
    static final int SIZE_WIDE = 2;
    static final int SIZE_LARGE = 3;

    /** Which of the two widgets this provider renders. */
    protected abstract int mode();

    @Override
    public void onUpdate(Context context, AppWidgetManager manager, int[] ids) {
        updateAll(context, manager, ids, mode());
    }

    @Override
    public void onAppWidgetOptionsChanged(Context context, AppWidgetManager manager, int id, Bundle options) {
        // Resizing 2x2 -> 2x4 -> 4x4 -> 4x2 changes the layout, not just padding.
        // Paint from the bundle the system just handed us: the manager's stored
        // options can still hold the previous size at this point.
        updateOne(context, manager, id, mode(), options);
    }

    @Override
    public void onReceive(Context context, Intent intent) {
        super.onReceive(context, intent);
        if (intent != null && ACTION_REFRESH.equals(intent.getAction())) {
            refreshAll(context);
        }
    }

    /** Rebuilds every placed widget of both kinds. Safe when none are placed. */
    public static void refreshAll(Context context) {
        try {
            Context app = context.getApplicationContext();
            AppWidgetManager manager = AppWidgetManager.getInstance(app);
            updateAll(app, manager, manager.getAppWidgetIds(new ComponentName(app, DaysWidgetProvider.class)), MODE_DAYS);
            updateAll(app, manager, manager.getAppWidgetIds(new ComponentName(app, ClockWidgetProvider.class)), MODE_CLOCK);
        } catch (Throwable ignored) {
            // Never let a widget failure break the caller.
        }
    }

    /** Queues a count logged from the widget for the web app to import. */
    public static void appendPendingLog(Context context, int count) {
        try {
            SharedPreferences sp = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE);
            JSONArray arr = new JSONArray();
            String raw = sp.getString(KEY_PENDING, "");
            if (raw != null && raw.length() > 0) {
                try {
                    arr = new JSONArray(raw);
                } catch (Throwable ignored) {
                    arr = new JSONArray();
                }
            }
            JSONObject item = new JSONObject();
            long now = System.currentTimeMillis();
            item.put("id", "widget_" + now);
            item.put("ts", now);
            item.put("count", Math.max(1, Math.min(99, count)));
            arr.put(item);
            sp.edit().putString(KEY_PENDING, arr.toString()).commit();
        } catch (Throwable ignored) {
            // The dialog still closes; the app just misses this one.
        }
    }

    private static void updateAll(Context context, AppWidgetManager manager, int[] ids, int mode) {
        if (ids == null) return;
        for (int id : ids) {
            updateOne(context, manager, id, mode);
        }
    }

    private static void updateOne(Context context, AppWidgetManager manager, int id, int mode) {
        updateOne(context, manager, id, mode, null);
    }

    private static void updateOne(Context context, AppWidgetManager manager, int id, int mode, Bundle options) {
        try {
            manager.updateAppWidget(id, build(context, manager, id, mode, options));
        } catch (Throwable ignored) {
            // Keep the other instances alive.
        }
    }

    private static int layoutFor(int size) {
        if (size == SIZE_TALL) return R.layout.widget_tall;
        if (size == SIZE_WIDE) return R.layout.widget_wide;
        if (size == SIZE_LARGE) return R.layout.widget_large;
        return R.layout.widget_small;
    }

    private static Bundle optionsFor(AppWidgetManager manager, int id, Bundle given) {
        if (given != null && !given.isEmpty()) return given;
        try {
            Bundle stored = manager.getAppWidgetOptions(id);
            if (stored != null) return stored;
        } catch (Throwable ignored) {
            // Fall through to the compact size.
        }
        return new Bundle();
    }

    /**
     * The options bundle holds a size *range*, not one size: a launcher fills in
     * min width / max height for portrait and max width / min height for
     * landscape. Reading the max of all four (as this used to) mixes the two
     * orientations, so a 2x2 phone widget looks 4 columns wide and the layout
     * never changes when the user resizes it. Ask the current orientation which
     * end of the range is the live size instead.
     *
     * Sizes are dp. A cell is ~70dp, so 2 cells report ~110dp, 3 cells ~180dp
     * and 4 cells ~250dp; 185dp separates "two cells" from "three or more".
     */
    private static int sizeClass(Context context, AppWidgetManager manager, int id, Bundle options) {
        Bundle o = optionsFor(manager, id, options);
        boolean portrait = context.getResources().getConfiguration().orientation
                != Configuration.ORIENTATION_LANDSCAPE;
        int w = o.getInt(portrait ? AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH
                                  : AppWidgetManager.OPTION_APPWIDGET_MAX_WIDTH, 0);
        int h = o.getInt(portrait ? AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT
                                  : AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT, 0);
        if (w <= 0) w = o.getInt(AppWidgetManager.OPTION_APPWIDGET_MAX_WIDTH, 0);
        if (h <= 0) h = o.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT, 0);
        if (w <= 0) w = 110;
        if (h <= 0) h = 110;
        boolean wide = w >= 185;
        boolean tall = h >= 185;
        if (wide && tall) return SIZE_LARGE;
        if (wide) return SIZE_WIDE;
        if (tall) return SIZE_TALL;
        return SIZE_SMALL;
    }

    static final class Data {
        long quit;
        double perDay;
        double packSize = 20;
        double packCost;
        String currency = "\u09F3";
        long logged;
        long elapsed;
        long days;
        long hours;
        long mins;
        long avoided;
        double saved;
        String since = "";
    }

    private static Data read(Context context) {
        Data d = new Data();
        try {
            SharedPreferences sp = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE);
            d.quit = parseLong(sp.getString("unlit_quit_date", ""), 0L);
            d.perDay = parseDouble(sp.getString("unlit_cigs_per_day", ""), 0);
            d.packSize = parseDouble(sp.getString("unlit_pack_size", ""), 20);
            d.packCost = parseDouble(sp.getString("unlit_pack_cost", ""), 0);
            d.logged = parseLong(sp.getString("unlit_logged_total", ""), 0L);
            String cur = sp.getString("unlit_currency", "\u09F3");
            if (cur != null && cur.length() > 0) d.currency = cur;
        } catch (Throwable ignored) {
            // Unreadable prefs: the setup state below is still valid.
        }

        if (d.quit > 0L) {
            d.elapsed = Math.max(0L, System.currentTimeMillis() - d.quit);
            d.days = d.elapsed / 86400000L;
            d.hours = (d.elapsed % 86400000L) / 3600000L;
            d.mins = (d.elapsed % 3600000L) / 60000L;
            double daysExact = d.elapsed / 86400000.0;
            long baseline = (long) Math.floor(daysExact * d.perDay);
            d.avoided = Math.max(0L, baseline - d.logged);
            d.saved = d.packSize > 0 ? (d.avoided / d.packSize) * d.packCost : 0;
            try {
                d.since = new SimpleDateFormat("MMM d", Locale.US).format(new Date(d.quit)).toUpperCase(Locale.US);
            } catch (Throwable ignored) {
                d.since = "";
            }
        }
        return d;
    }

    /** "8m", "5h 42m", "12d 4h" — the time widget's hero. */
    static String elapsedShort(Data d) {
        if (d.elapsed >= 86400000L) return d.days + "d " + d.hours + "h";
        if (d.elapsed >= 3600000L) return d.hours + "h " + two(d.mins) + "m";
        return d.mins + "m";
    }

    /** "12d 4h 05m" — the days widget's supporting line. */
    static String elapsedLong(Data d) {
        if (d.elapsed >= 86400000L) return d.days + "d " + d.hours + "h " + two(d.mins) + "m";
        if (d.elapsed >= 3600000L) return d.hours + "h " + two(d.mins) + "m";
        return d.mins + "m";
    }

    private static String two(long n) {
        return n < 10 ? "0" + n : String.valueOf(n);
    }

    private static boolean isNight(Context context) {
        int mask = context.getResources().getConfiguration().uiMode & Configuration.UI_MODE_NIGHT_MASK;
        return mask == Configuration.UI_MODE_NIGHT_YES;
    }

    private static float heroSize(int size, int length) {
        float base;
        if (size == SIZE_SMALL) base = 40f;
        else if (size == SIZE_TALL) base = 54f;
        else if (size == SIZE_WIDE) base = 40f;
        else base = 60f;
        if (length >= 9) base *= 0.62f;
        else if (length >= 7) base *= 0.75f;
        else if (length >= 6) base *= 0.87f;
        return base;
    }

    private static RemoteViews build(Context context, AppWidgetManager manager, int id, int mode, Bundle options) {
        Data d = read(context);
        boolean night = isNight(context);
        int size = sizeClass(context, manager, id, options);

        RemoteViews v = new RemoteViews(context.getPackageName(), layoutFor(size));

        int fg = night ? 0xFFFFFFFF : 0xFF0A0A0A;
        int muted = night ? 0xFF8A8A8A : 0xFF71717A;
        int line = night ? 0xFF2E2E2E : 0xFFE4E4E7;

        v.setInt(R.id.widget_root, "setBackgroundResource",
                night ? R.drawable.widget_bg_dark : R.drawable.widget_bg_light);
        v.setTextColor(R.id.label, muted);
        v.setTextColor(R.id.hero, fg);
        v.setTextColor(R.id.sub, muted);
        v.setTextColor(R.id.stat1_value, fg);
        v.setTextColor(R.id.stat1_label, muted);
        v.setTextColor(R.id.stat2_value, fg);
        v.setTextColor(R.id.stat2_label, muted);
        v.setTextColor(R.id.hint, muted);
        v.setInt(R.id.divider, "setBackgroundColor", line);

        String hero;
        String label;
        String sub;
        String hint;

        if (d.quit <= 0L) {
            hero = "--";
            label = "UNLIT";
            sub = "OPEN THE APP TO SET UP";
            hint = "";
        } else if (mode == MODE_CLOCK) {
            hero = elapsedShort(d);
            label = "SMOKE-FREE FOR";
            sub = d.days == 0L
                    ? "SINCE " + d.since
                    : d.days + (d.days == 1L ? " DAY" : " DAYS") + "  \u00B7  SINCE " + d.since;
            hint = "TAP TO OPEN UNLIT";
        } else if (d.days < 1L) {
            // Under a day a bare "0" would be a lie; show the clock instead.
            hero = elapsedShort(d);
            label = "SMOKE-FREE FOR";
            sub = "SINCE " + d.since;
            hint = "TAP THE NUMBER TO LOG";
        } else {
            hero = String.valueOf(d.days);
            label = d.days == 1L ? "DAY SMOKE-FREE" : "DAYS SMOKE-FREE";
            sub = elapsedLong(d);
            hint = "TAP THE NUMBER TO LOG";
        }

        v.setTextViewText(R.id.label, label);
        v.setTextViewText(R.id.hero, hero);
        v.setTextViewText(R.id.sub, sub);
        v.setTextViewText(R.id.hint, hint);
        v.setTextViewTextSize(R.id.hero, TypedValue.COMPLEX_UNIT_SP, heroSize(size, hero.length()));

        if (d.quit <= 0L) {
            v.setTextViewText(R.id.stat1_value, "--");
            v.setTextViewText(R.id.stat2_value, "--");
        } else {
            v.setTextViewText(R.id.stat1_value, String.format(Locale.US, "%,d", d.avoided));
            v.setTextViewText(R.id.stat2_value, d.currency + String.format(Locale.US, "%,.0f", d.saved));
        }
        v.setTextViewText(R.id.stat1_label, "NOT SMOKED");
        v.setTextViewText(R.id.stat2_label, "SAVED");

        v.setViewVisibility(R.id.stats_row, size == SIZE_SMALL ? View.GONE : View.VISIBLE);
        v.setViewVisibility(R.id.divider, size == SIZE_TALL || size == SIZE_LARGE ? View.VISIBLE : View.GONE);
        v.setViewVisibility(R.id.hint, size == SIZE_TALL || size == SIZE_LARGE ? View.VISIBLE : View.GONE);

        try {
            Intent launch = context.getPackageManager().getLaunchIntentForPackage(context.getPackageName());
            PendingIntent openApp = null;
            if (launch != null) {
                openApp = PendingIntent.getActivity(context, 0, launch,
                        PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
            }

            // Tapping the number on the days widget asks how many, right there.
            Intent log = new Intent(context, SmokeQuickLogActivity.class);
            log.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TOP);
            PendingIntent logDialog = PendingIntent.getActivity(context, 1, log,
                    PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
            v.setOnClickPendingIntent(R.id.hero, logDialog);
            v.setOnClickPendingIntent(R.id.widget_root, openApp != null ? openApp : logDialog);
        } catch (Throwable ignored) {
            // Tapping does nothing rather than crashing the launcher.
        }

        return v;
    }

    private static long parseLong(String s, long fallback) {
        if (s == null) return fallback;
        try { return Long.parseLong(s.trim()); } catch (Exception e) { return fallback; }
    }

    private static double parseDouble(String s, double fallback) {
        if (s == null) return fallback;
        try { return Double.parseDouble(s.trim()); } catch (Exception e) { return fallback; }
    }
}
EOF
sed -i "s/__APP_ID__/$APP_ID/g" "$PKG_DIR/UnlitWidgetBase.java"

cat > "$PKG_DIR/DaysWidgetProvider.java" <<'EOF'
