# ---------------------------------------------------------------------------
# MainActivity is still the reliable moment to refresh after the web layer
# writes new values.
# ---------------------------------------------------------------------------
cat > "$PKG_DIR/MainActivity.java" <<'EOF'
package __APP_ID__;

import android.os.Bundle;
import com.getcapacitor.BridgeActivity;

public class MainActivity extends BridgeActivity {
    @Override
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        UnlitWidgetBase.refreshAll(this);
        // The web layer writes its values a moment later, so refresh once more
        // after the first paint instead of waiting for the user to leave.
        new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(
            () -> UnlitWidgetBase.refreshAll(this), 2500L);
    }

    @Override
    public void onResume() {
        super.onResume();
        UnlitWidgetBase.refreshAll(this);
    }

    @Override
    public void onPause() {
        UnlitWidgetBase.refreshAll(this);
        super.onPause();
    }
}
EOF
sed -i "s/__APP_ID__/$APP_ID/g" "$PKG_DIR/MainActivity.java"

MANIFEST="$MAIN/AndroidManifest.xml"

# Drop the old single receiver, then add both widgets plus the dialog activity.
python3 - "$MANIFEST" <<'PY'
import re, sys
path = sys.argv[1]
src = open(path, encoding='utf-8').read()

# Remove any widget/dialog block from a previous run of this script. The
# android:name attribute sits on its own line in the generated XML, so the
# patterns have to allow newlines and other attributes between the tag and it.
src = re.sub(
    r'\s*<receiver\b[^>]*?android:name="\.(?:Quit|Days|Clock)WidgetProvider".*?</receiver>',
    '', src, flags=re.S)
src = re.sub(
    r'\s*<activity\b[^>]*?android:name="\.SmokeQuickLogActivity".*?(?:/>|</activity>)',
    '', src, flags=re.S)

receivers = '''
        <receiver
            android:name=".DaysWidgetProvider"
            android:exported="true"
            android:label="@string/widget_days_name">
            <intent-filter>
                <action android:name="android.appwidget.action.APPWIDGET_UPDATE" />
                <action android:name="com.unlit.app.REFRESH_WIDGET" />
            </intent-filter>
            <meta-data
                android:name="android.appwidget.provider"
                android:resource="@xml/days_widget_info" />
        </receiver>

        <receiver
            android:name=".ClockWidgetProvider"
            android:exported="true"
            android:label="@string/widget_clock_name">
            <intent-filter>
                <action android:name="android.appwidget.action.APPWIDGET_UPDATE" />
                <action android:name="com.unlit.app.REFRESH_WIDGET" />
            </intent-filter>
            <meta-data
                android:name="android.appwidget.provider"
                android:resource="@xml/clock_widget_info" />
        </receiver>

        <activity
            android:name=".SmokeQuickLogActivity"
            android:exported="false"
            android:excludeFromRecents="true"
            android:theme="@style/UnlitQuickLog"
            android:windowSoftInputMode="stateVisible|adjustResize" />
'''

# Match the closing tag whatever the surrounding indentation is, so a manifest
# formatted differently by a future Capacitor release still gets the widgets.
if '</application>' not in src:
    raise SystemExit('AndroidManifest.xml has no </application> to insert into')
src = re.sub(r'[ \t]*</application>', lambda m: receivers + '    </application>', src, count=1)
open(path, 'w', encoding='utf-8').write(src)
PY

echo "Widgets added for $APP_ID"
